import React, { useState } from 'react';
import Button from '@mui/material/Button';
import { AiOutlineMenuFold, AiOutlineMenuUnfold } from "react-icons/ai";

function Header() {
  const [menuOpen, setMenuOpen] = useState(false);

  const handleMenuToggle = () => {
    setMenuOpen(!menuOpen);
  };

  return (
    <header className="w-full py-3 px-6 shadow-md bg-[#1e88e5] flex items-center justify-between text-white">
      
      {/* Left Section: Menu Button */}
      <div className="flex items-center">
        <Button
          onClick={handleMenuToggle}
          sx={{
            width: 42,
            height: 42,
            minWidth: 42,
            borderRadius: '50%',
            backgroundColor: 'rgba(255,255,255,0.2)',
            '&:hover': { backgroundColor: 'rgba(255,255,255,0.3)' },
          }}
        >
          {menuOpen ? (
            <AiOutlineMenuUnfold size={22} color="#fff" />
          ) : (
            <AiOutlineMenuFold size={22} color="#fff" />
          )}
        </Button>
      </div>

      {/* Center Title */}
      <h1 className="text-xl font-semibold tracking-wide drop-shadow-md">
        My Dashboard
      </h1>

      {/* Right Section: Sign-in Button */}
      <div className="flex items-center gap-3">
        <Button
          variant="contained"
          sx={{
            backgroundColor: '#ff5252',
            color: '#fff',
            textTransform: 'none',
            px: 3,
            py: 1,
            borderRadius: '8px',
            boxShadow: 3,
            '&:hover': { backgroundColor: '#ff7070' },
          }}
        >
          Sign in
        </Button>
      </div>
    </header>
  );
}

export default Header;
